import{_ as t,a,o as n,a4 as o}from"./chunks/framework.-FZumj2l.js";const m=JSON.parse(`{"title":"Admin Authentication","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-authenticated-query","title":"Authenticated Query","description":"Every Admin GraphQL request carries the admin Bearer token. This example reads the authenticated admin's own profile to confirm the token works.","query":"query {\\n  readAdminProfile {\\n    id\\n    name\\n    email\\n    status\\n  }\\n}\\n","variables":"{}\\n","response":"{\\n  \\"data\\": {\\n    \\"readAdminProfile\\": {\\n      \\"id\\": \\"/api/admin/admin_profiles/4\\",\\n      \\"name\\": \\"Admin User\\",\\n      \\"email\\": \\"admin@example.com\\",\\n      \\"status\\": \\"1\\"\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/authentication.md","filePath":"api/graphql-api/admin/authentication.md","lastUpdated":1783420618000}`),i={name:"api/graphql-api/admin/authentication.md"};function r(s,e,d,l,h,p){return n(),a("div",null,e[0]||(e[0]=[o(`<h1 id="admin-authentication" tabindex="-1">Admin Authentication <a class="header-anchor" href="#admin-authentication" aria-label="Permalink to &quot;Admin Authentication&quot;">​</a></h1><p>The Bagisto Admin GraphQL API authenticates every request with a pre-issued <strong>Integration token</strong>. There is no login mutation — you generate a token once in the admin panel and send it on every request.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/admin/graphql</span></span>
<span class="line"><span>Authorization: Bearer &lt;id&gt;|&lt;token&gt;</span></span>
<span class="line"><span>Content-Type: application/json</span></span></code></pre></div><p>Admin GraphQL has its <strong>own</strong> endpoint, separate from the shop GraphQL endpoint (<code>POST /api/graphql</code>). The admin endpoint authenticates with the Bearer token <strong>only</strong> — the storefront key is not used here. An interactive playground is available at <code>GET /api/admin/graphiql</code>.</p><h2 id="how-to-authenticate" tabindex="-1">How to authenticate <a class="header-anchor" href="#how-to-authenticate" aria-label="Permalink to &quot;How to authenticate&quot;">​</a></h2><ol><li>In the admin panel, open the <strong>Integration</strong> menu (<code>Admin → Integration</code>) and generate a token.</li><li>Copy the token the moment it is shown — it is displayed <strong>once</strong>.</li><li>Send it on every Admin GraphQL request as a Bearer token:</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Authorization: Bearer &lt;id&gt;|&lt;token&gt;</span></span></code></pre></div><h2 id="about-the-token" tabindex="-1">About the token <a class="header-anchor" href="#about-the-token" aria-label="Permalink to &quot;About the token&quot;">​</a></h2><ul><li>The token belongs to a specific admin user and carries that admin&#39;s permissions. A request can never do more than the owning admin is allowed to do.</li><li>The plaintext format is <code>&lt;id&gt;|&lt;random&gt;</code>. Send it verbatim.</li><li>A token can be locked down with scoped <strong>permissions</strong>, an <strong>IP allowlist</strong>, an <strong>expiry date</strong>, and <strong>rate limits</strong> — see <a href="#token-security">Token security</a> below.</li><li>Revoke or regenerate a token at any time from the same <strong>Integration</strong> menu. A revoked token stops working immediately.</li></ul><h2 id="token-security" tabindex="-1">Token security <a class="header-anchor" href="#token-security" aria-label="Permalink to &quot;Token security&quot;">​</a></h2><p>Each Integration token can be locked down at generation time in the <strong>Integration</strong> menu. Four independent controls scope what a token can do:</p><h3 id="permissions-acl" tabindex="-1">Permissions (ACL) <a class="header-anchor" href="#permissions-acl" aria-label="Permalink to &quot;Permissions (ACL)&quot;">​</a></h3><p>A token is tied to one admin and <strong>inherits that admin&#39;s role permissions</strong> — it can never do more than its owner. When generating the token you choose a permission mode:</p><ul><li><strong>All</strong> — every action the owner&#39;s role allows.</li><li><strong>Custom</strong> — a specific subset of permissions you select, frozen onto the token.</li><li><strong>Same as web</strong> — always mirrors the owner&#39;s current role, so the token automatically follows any later changes to that role.</li></ul><p>A query or mutation for an action the token isn&#39;t permitted to perform fails with a <strong>Forbidden</strong> entry in the GraphQL <code>errors[]</code>.</p><h3 id="ip-allowlist" tabindex="-1">IP allowlist <a class="header-anchor" href="#ip-allowlist" aria-label="Permalink to &quot;IP allowlist&quot;">​</a></h3><p>Optionally restrict a token to specific client IPs. Individual <strong>IPv4</strong> and <strong>IPv6</strong> addresses and <strong>CIDR ranges</strong> are all supported. Leave the allowlist empty to allow any IP. A request from an address that isn&#39;t on the list is rejected as <strong>401 Unauthenticated</strong>. (<code>127.0.0.1</code> is always allowed, for local development.)</p><h3 id="expiry" tabindex="-1">Expiry <a class="header-anchor" href="#expiry" aria-label="Permalink to &quot;Expiry&quot;">​</a></h3><p>A token can have an <strong>expiry date</strong> (default: one year after generation) or be set to <strong>never expire</strong>. After the expiry date the token stops working (<strong>401</strong>).</p><h3 id="rate-limits" tabindex="-1">Rate limits <a class="header-anchor" href="#rate-limits" aria-label="Permalink to &quot;Rate limits&quot;">​</a></h3><p>Each token is throttled by two independent buckets:</p><table tabindex="0"><thead><tr><th>Bucket</th><th>Default</th></tr></thead><tbody><tr><td>Per minute</td><td>60 requests</td></tr><tr><td>Per day</td><td>10,000 requests</td></tr></tbody></table><p>Exceeding either limit returns <strong>429 Too Many Requests</strong>.</p><p><strong>Unlimited rate limit</strong> — when generating or editing the token, choose the <strong>Unlimited</strong> option for the per-minute and/or per-day limit. That removes the cap for that bucket; set <strong>both</strong> to Unlimited for a fully unthrottled token.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Condition</th><th>Result</th></tr></thead><tbody><tr><td>Missing / malformed / expired / revoked token, or client IP not on the token&#39;s allowlist</td><td><code>401 Unauthenticated</code></td></tr><tr><td>Token valid but lacks permission for the action</td><td>GraphQL <code>errors[]</code> (Forbidden)</td></tr><tr><td>Per-minute or per-day rate limit exceeded</td><td><code>429 Too Many Requests</code></td></tr></tbody></table><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><p>Use the interactive example on the right to see an authenticated request in GraphQL, cURL, Node.js, React, and PHP.</p>`,29)]))}const u=t(i,[["render",r]]);export{m as __pageData,u as default};
